#include <iostream>
int main() {
    int w;
    if (!(std::cin >> w)) return 0;
    std::cout << ((w > 2 && w % 2 == 0) ? "YES" : "NO") << '\n';
}

#include <iostream>
#include <string>
int main() {
    int n;
    if (!(std::cin >> n)) return 0;
    for (int i = 0; i < n; ++i) {
        std::string word;
        std::cin >> word;
        if (word.size() > 10) {
            std::cout << word.front() << word.size() - 2 << word.back();
        } else {
            std::cout << word;
        }
        std::cout << '\n';
    }
}
